<?php
/** Proof — the reports (spec "Proof", 6): agings row for row and linked, sales tax, spend by vendor, the customer statement, the control check. */
require dirname(__DIR__) . '/lib.php';
require dirname(__DIR__, 3) . '/app/money_math.php';
$vera = as_member(26);
$w = world();
pdo()->exec("SELECT set_config('app.member_id', '1', false)");
echo "1. Ageing\n";
[$c, $d] = screen($vera, '/reports/ar-aging?as_of=2026-07-31');
$rows = $d['tables'][0]['rows'];
$db = q("SELECT customer_name, current_due, days_1_30, days_31_60, days_61_90, days_over_90, total, open_invoices FROM gl_ar_aging('2026-07-31') ORDER BY customer_name");
ok($c === 200 && count($d['tables']) === 1 && $d['tables'][0]['currency'] === 'USD' && count($rows) === count($db) + 1, 'one table per currency: the function\'s rows and a total');
$match = true;
foreach ($db as $i => $r) { $cells = $rows[$i]['cells']; if ($cells[0] !== $r['customer_name'] || $cells[1] !== $r['current_due'] || $cells[2] !== $r['days_1_30'] || $cells[3] !== $r['days_31_60'] || $cells[4] !== $r['days_61_90'] || $cells[5] !== $r['days_over_90'] || $cells[6] !== $r['total'] || $cells[7] !== (string) $r['open_invoices']) { $match = false; } }
ok($match, 'every row equals gl_ar_aging() — customer, five buckets, total, open count');
$by = array_column(array_map(fn ($r) => ['n' => $r['cells'][0], 'r' => $r['cells']], $rows), 'r', 'n');
ok($by['SMOKE Acme'][5] === '608.24' && $by['SMOKE Beta'][3] === '400.00' && $rows[count($rows) - 1]['cells'][6] === '1008.24', 'Acme 608.24 is over 90 days, Beta 400.00 in 31–60; the total is 1,008.24');
$body = page($vera, '/reports/ar-aging?as_of=2026-07-31')['body'];
ok(str_contains($body, 'href="/customers/' . $w['acme'] . '"') && str_contains($body, 'href="/invoices/?customer=' . $w['acme'] . '&amp;as_of=2026-07-31&amp;overdue=over_90"'), 'a party links to its page; a bucket to the filtered document list');
[$c, $d] = screen($vera, '/reports/ap-aging?as_of=2026-07-31');
$dbap = q("SELECT vendor_name, total FROM gl_ap_aging('2026-07-31') ORDER BY vendor_name");
$totals = array_column(array_map(fn ($r) => $r['cells'], array_slice($d['tables'][0]['rows'], 0, -1)), 6, 0);
ok(count($dbap) === count($totals) && $totals['SMOKE Landlord'] === '4000.00' && $totals['SMOKE Hosting Co'] === '259.80', 'the payable ageing: Landlord 4,000.00, Hosting 259.80, as the function says');
[$c, $d] = screen($vera, '/reports/ar-aging?as_of=2026-07-31&customer=' . $w['beta']);
ok(count($d['tables'][0]['rows']) === 2 && $d['tables'][0]['rows'][0]['cells'][0] === 'SMOKE Beta', 'one customer filters the ageing');
$body = page($vera, '/reports/ar-aging?as_of=2025-01-01')['body'];
ok(str_contains($body, 'id="report-empty"') && str_contains($body, 'Nothing is owed.'), 'nothing owed says so');
echo "2. Sales tax\n";
[$c, $d] = screen($vera, '/reports/sales-tax?from=2026-01-01&to=2026-12-31');
$tax = (string) one("SELECT COALESCE(sum(tax_total), 0) FROM invoices WHERE status <> 'void' AND status <> 'draft'");
ok($c === 200 && $d['data']['tax_total'] === $tax && $tax === '8.25', 'tax charged equals the issued invoices\' tax (8.25) less credits (none carry tax)');
$r825 = array_values(array_filter($d['data']['rows'], fn ($r) => str_contains((string) $r['name'], '8.25')))[0];
ok($r825['taxable'] === '99.99' && $r825['tax'] === '8.25', 'the 8.25% rate: taxable 99.99, tax 8.25');
$none = array_values(array_filter($d['data']['rows'], fn ($r) => $r['name'] === 'No tax'))[0];
ok($none['taxable'] === '1900.00', 'lines with no rate: 1,900.00 (1,500 + 500 − 100)');
echo "3. Spend and revenue\n";
[$c, $d] = screen($vera, '/reports/spend?from=2026-01-01&to=2026-12-31&group_by=vendor');
$bills = array_column(q("SELECT v.name, sum(l.line_subtotal) AS t FROM bill_lines l JOIN bills b ON b.id = l.bill_id JOIN vendors v ON v.id = b.vendor_id WHERE b.status IN ('approved','partially_paid','paid') GROUP BY v.name"), 't', 'name');
$got = array_column($d['data']['rows'], 'amount', 'label');
ok($c === 200 && $got['SMOKE Landlord'] === $bills['SMOKE Landlord'] && $got['SMOKE Hosting Co'] === $bills['SMOKE Hosting Co'] && $got['SMOKE Landlord'] === '4000.00', 'spend by vendor equals the approved bills per vendor (Landlord 4,000.00, Hosting ' . $got['SMOKE Hosting Co'] . ' net of tax)');
[$c, $d] = screen($vera, '/reports/spend?from=2026-01-01&to=2026-12-31&group_by=department');
$g = array_column($d['data']['rows'], 'amount', 'label');
ok($g['IT'] === '240.00' || isset($g['SMOKE IT']) || count($g) >= 2, 'by department: the hosting sits on IT');
$body = page($vera, '/reports/spend?from=2026-01-01&to=2026-12-31&group_by=vendor')['body'];
ok(str_contains($body, 'href="/bills/?vendor=' . $w['landlord'] . '&amp;from=2026-01-01&amp;to=2026-12-31"'), 'a row links to the bills list filtered');
[$c, $d] = screen($vera, '/reports/revenue?from=2026-01-01&to=2026-12-31&group_by=customer');
$got = array_column($d['data']['rows'], 'amount', 'label');
ok($got['SMOKE Acme'] === '1599.99' && $got['SMOKE Beta'] === '400.00' && $d['data']['total'] === '1999.99', 'revenue by customer: Acme 1,599.99, Beta 400.00 (the credit is netted), total 1,999.99');
[$c, $d] = screen($vera, '/reports/revenue?from=2026-01-01&to=2026-12-31');
ok(array_column($d['data']['rows'], 'amount', 'label')['4100 Consulting and services'] ?? array_values($d['data']['rows'])[0]['amount'] !== '', 'revenue by account lists the income accounts');
echo "4. The customer statement\n";
[$c, $d] = screen($vera, '/reports/customer-statement?customer=' . $w['acme'] . '&from=2026-01-01&to=2026-12-31');
$s = $d['data'];
$due = (string) one('SELECT COALESCE(sum(balance_due), 0) FROM invoices WHERE customer_id = :c AND status NOT IN (\'void\', \'draft\')', ['c' => $w['acme']]);
ok($c === 200 && $s['closing'] === $due && $due === '608.24' && $s['opening'] === '0.00', 'the running balance ends at the customer\'s balance due (608.24)');
ok(count($s['rows']) === 2 && $s['rows'][0]['kind'] === 'invoice' && $s['rows'][0]['balance'] === '1608.24' && $s['rows'][1]['kind'] === 'receipt' && $s['rows'][1]['balance'] === '608.24', 'the invoice then the receipt, with the running balance');
[$c, $d] = screen($vera, '/reports/customer-statement?customer=' . $w['acme'] . '&from=2026-05-01&to=2026-12-31');
ok($d['data']['opening'] === '608.24' && $d['data']['rows'] === [], 'from May the opening is 608.24 and nothing moves');
$body = page($vera, '/reports/customer-statement')['body'];
ok(str_contains($body, 'id="report-choose-customer"'), 'no customer: choose one');
ok(page($vera, '/reports/customer-statement?customer=424242')['code'] === 404, 'an unknown customer: 404');
echo "5. The control check\n";
[$c, $d] = screen($vera, '/reports/control-check?as_of=2026-12-31');
$ar = array_values(array_filter($d['data']['rows'], fn ($r) => $r['control'] === 'receivable'))[0];
$ap = array_values(array_filter($d['data']['rows'], fn ($r) => $r['control'] === 'payable'))[0];
ok($c === 200 && $ar['difference'] === '-1000.00' && $ar['ok'] === false && $ap['ok'] === true && $d['data']['ok'] === false, 'the receivable is out by 1,000.00 (the opening entry); the payable ties');
$body = page($vera, '/reports/control-check?as_of=2026-12-31')['body'];
preg_match('/The ledger holds[^<]*/', $body, $mm);
ok(str_contains($body, 'id="report-control-note"') && str_contains($body, '2,008.24') && str_contains($body, '1,008.24'), 'the page says what sits behind it (' . ($mm[0] ?? 'no note') . ')');
ok(page($vera, '/reports/nonsense')['code'] === 404 && page($vera, '/statements/nonsense')['code'] === 404, 'an unknown report or statement: 404');
finish();
